function lenteraCount($conn,$table){$allowed=['buku','users','pesanan','kategori'];if(!in_array($table,$allowed,true))return 0;$r=mysqli_query($conn,'SELECT COUNT(*) AS total FROM '.$table);$x=$r?mysqli_fetch_assoc($r):null;return (int)($x['total']??0);}
$total_buku=lenteraCount($conn,'buku');$total_user=lenteraCount($conn,'users');$total_pesanan=lenteraCount($conn,'pesanan');$total_kategori=lenteraCount($conn,'kategori');
$q=mysqli_query($conn,"SELECT COALESCE(SUM(total),0) AS pemasukan FROM pesanan WHERE status_pembayaran='Sudah Bayar'");$pemasukan=$q?(float)(mysqli_fetch_assoc($q)['pemasukan']??0):0;
?>
